def _handle_component_inventory(
    method: str,
    environ: dict[str, Any],
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    # The inventory is read-only: a declared non-empty (or malformed) body
    # is a bad request without consulting any business data. An omitted
    # header and an explicit zero length are accepted as an empty body.
    body_error = _bodyless_request_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    # Only the optional ``name`` filter is accepted; unknown or repeated
    # parameters and an empty value are rejected before any data is read.
    name, query_error = _parse_component_inventory_query(
        str(environ.get("QUERY_STRING", ""))
    )
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    # Computed on the fly from the current stores: entries unfold in
    # resource registration order, and within one resource the components
    # keep their SBOM submission order. Resources without an SBOM document
    # are skipped silently, and a document with an empty component list
    # contributes no entries. Each record puts the owning resource id
    # first, followed by the component name and version echoed verbatim
    # and the component digest in its registered lowercase form. Nothing
    # is recorded and no state is touched.
    inventory: list[dict[str, object]] = []
    for resource in store.list_all():
        document = sbom_store.get_sbom(resource.id)
        if document is None:
            continue
        for component in document.components:
            if name is not None and component.name != name:
                continue
            inventory.append(
                {
                    "resource_id": resource.id,
                    "name": component.name,
                    "version": component.version,
                    "digest": component.digest,
                }
            )
    return _json_response(
        start_response,
        "200 OK",
        inventory,
        trailing_newline=True,
    )


def _handle_notifications_post(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:
    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    # Validate the whole body before touching any store, so a bad request
    # can never leave a partial record and always answers 400 (even for a
    # resource that does not exist).
    try:
        build_notification_fields(payload)
    except NotificationValidationError as exc:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            exc.message,
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    record = notification_store.add(raw_id, payload)
    return _json_response(
        start_response,
        "201 Created",
        record.to_dict(),
        trailing_newline=True,
